import React from 'react';
import {createRoot} from 'react-dom/client';
import {ThemeProvider} from '@easypost/easy-ui/Theme';
import {InvestigationWorkbench} from '@easypost/easy-ui/InvestigationWorkspace';
import '@easypost/easy-ui/style.css';
import '@easypost/easy-ui/NetworkMap/maplibre-gl.css';
import workerUrl from '@easypost/easy-ui/NetworkMap/maplibre-gl-worker.mjs?worker&url';
const params=new URLSearchParams(location.search);
const dark=params.has('dark');
const shared=params.has('shared');
const colors=dark?['#8caaff','#ffad61']:['#164dff','#f2780a'];
const locations=[{id:'a',label:'Synthetic A',coordinates:[-100,40],kind:'hub'},{id:'b',label:'Synthetic B',coordinates:[-98,41],kind:'hub'}];
const events=[{id:'event-a1',label:'Blue observation A',locationId:'a',timeLabel:'08:00'},{id:'event-b1',label:'Blue observation B',locationId:'b',timeLabel:'09:00'},{id:'event-a2',label:'Orange observation A',locationId:'a',timeLabel:'10:00'},{id:'event-b2',label:'Orange observation B',locationId:'b',timeLabel:'11:00'}];
const connections=[{id:'connection-blue',fromEventId:'event-a1',toEventId:'event-b1',segmentId:'segment-blue'},{id:'connection-orange',fromEventId:'event-a2',toEventId:'event-b2',segmentId:shared?'segment-blue':'segment-orange'}];
const segments=[{id:'segment-blue',from:'a',to:'b',label:'Synthetic blue connection',evidence:'transfer'},...shared?[]:[{id:'segment-orange',from:'a',to:'b',label:'Synthetic orange connection',evidence:'transfer'}]];
const graph={events,connections,locations,segments,paths:[{id:'blue',label:'Synthetic Blue',color:colors[0],connectionIds:['connection-blue']},{id:'orange',label:'Synthetic Orange',color:colors[1],connectionIds:['connection-orange']}]};
const mapStyle={version:8,sources:{},layers:[{id:'background',type:'background',paint:{'background-color':dark?'#19212e':'#edf2f7'}}]};
Object.assign(window,{syntheticGraph:graph});
createRoot(document.getElementById('root')!).render(<ThemeProvider colorScheme={dark?'dark':'light'}><main style={{maxWidth:1200,margin:'24px auto'}}><InvestigationWorkbench title={shared?'Shared segment identity control':'Distinct segment identities, coincident geometry'} showHistoryLabels graph={graph as any} map={{mapStyle:mapStyle as any,workerUrl,height:520,onMapReady:map=>Object.assign(window,{nativeMap:map})}}/></main></ThemeProvider>);
